function probe(params) {
  return Math.pow(1 + params.x, params.n);
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h, dark = state.dark;
  var fg = dark ? '#d7dee8' : '#263444';
  var grid = dark ? '#34404d' : '#dce2e9';
  var real = '#2f6fe4', approx = '#9aa4b2';
  var left = 54, right = w - 24, top = 25, bottom = h - 48;
  var xmax = 2, n = p.n;
  var ymax = Math.pow(1 + xmax, n) * 1.04;
  function X(x) { return left + (right - left) * x / xmax; }
  function Y(y) { return bottom - (bottom - top) * y / ymax; }
  ctx.clearRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.strokeStyle = grid;
  for (var i = 0; i <= 5; i++) {
    var yy = top + (bottom - top) * i / 5;
    ctx.beginPath(); ctx.moveTo(left, yy); ctx.lineTo(right, yy); ctx.stroke();
  }
  ctx.strokeStyle = fg;
  ctx.beginPath(); ctx.moveTo(left, top); ctx.lineTo(left, bottom); ctx.lineTo(right, bottom); ctx.stroke();
  ctx.setLineDash([6, 5]);
  ctx.strokeStyle = approx;
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (var j = 0; j <= 100; j++) {
    var xa = xmax * j / 100, ya = 1 + n * xa;
    if (j === 0) ctx.moveTo(X(xa), Y(ya)); else ctx.lineTo(X(xa), Y(ya));
  }
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.strokeStyle = real;
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (var k = 0; k <= 160; k++) {
    var xb = xmax * k / 160, yb = Math.pow(1 + xb, n);
    if (k === 0) ctx.moveTo(X(xb), Y(yb)); else ctx.lineTo(X(xb), Y(yb));
  }
  ctx.stroke();
  var x = p.x, px = X(x), actual = Math.pow(1 + x, n), linear = 1 + n * x;
  var ay = Y(actual), ly = Y(linear);
  ctx.strokeStyle = dark ? '#667789' : '#b5bec8';
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 4]);
  ctx.beginPath(); ctx.moveTo(px, bottom); ctx.lineTo(px, Math.min(ay, ly)); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = approx;
  ctx.beginPath(); ctx.arc(px, ly, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = real;
  ctx.beginPath(); ctx.arc(px, ay, 6, 0, Math.PI * 2); ctx.fill();
  if (actual > linear) {
    ctx.strokeStyle = real;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(px + 12, ly); ctx.lineTo(px + 12, ay); ctx.stroke();
  }
  ctx.fillStyle = fg;
  ctx.font = '13px sans-serif';
  ctx.fillText('x', right - 8, bottom + 25);
  ctx.fillText('(1 + x)ⁿ', 8, top + 8);
  ctx.fillStyle = real;
  ctx.fillText('exact', Math.min(right - 45, px + 14), Math.max(top + 14, ay - 10));
  ctx.fillStyle = approx;
  ctx.fillText('1 + nx', Math.min(right - 52, px + 14), Math.min(bottom - 8, ly + 20));
}

function probe(params) {
  return Math.cos(params.x * Math.PI / 180);
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h;
  var dark = state.dark;
  var ink = dark ? '#d7dde5' : '#27313d';
  var grid = dark ? '#46515f' : '#dfe4ea';
  var blue = '#2f6fe4', grey = '#9aa4b2';
  var maxX = 8e1, maxA = maxX * Math.PI / 180;
  var L = 58, R = w - 22, T = 24, B = h - 38;
  var pw = R - L, ph = B - T;
  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  function X(x) { return L + pw * x / maxA; }
  function Y(y) { return B - ph * (y + 0.08) / 1.16; }
  ctx.strokeStyle = grid;
  ctx.lineWidth = 1;
  for (var j = 0; j <= 4; j++) {
    var yy = T + ph * j / 4;
    ctx.beginPath(); ctx.moveTo(L, yy); ctx.lineTo(R, yy); ctx.stroke();
  }
  ctx.strokeStyle = ink;
  ctx.beginPath(); ctx.moveTo(L, T); ctx.lineTo(L, B); ctx.lineTo(R, B); ctx.stroke();
  ctx.fillStyle = dark ? '#202b38' : '#edf3fc';
  ctx.beginPath(); ctx.moveTo(X(0), Y(1));
  for (var i = 1; i <= 120; i++) {
    var a = maxX * i / 120 * Math.PI / 180;
    ctx.lineTo(X(a), Y(Math.cos(a)));
  }
  for (var k = 120; k >= 0; k--) {
    var b = maxX * k / 120 * Math.PI / 180;
    ctx.lineTo(X(b), Y(1 - b * b / 2));
  }
  ctx.closePath(); ctx.fill();
  function curve(f, color) {
    ctx.strokeStyle = color; ctx.lineWidth = 2.5;
    ctx.beginPath();
    for (var n = 0; n <= 160; n++) {
      var a = maxA * n / 160;
      if (n === 0) ctx.moveTo(X(a), Y(f(a)));
      else ctx.lineTo(X(a), Y(f(a)));
    }
    ctx.stroke();
  }
  curve(function(a) { return 1 - a * a / 2; }, grey);
  curve(Math.cos, blue);
  var a = p.x * Math.PI / 180;
  ctx.strokeStyle = grid; ctx.lineWidth = 1;
  ctx.setLineDash([4, 5]);
  ctx.beginPath(); ctx.moveTo(X(a), B); ctx.lineTo(X(a), Y(1)); ctx.stroke();
  ctx.setLineDash([]);
  var scan = a * (0.5 - 0.5 * Math.cos(state.t * 1.4));
  function dot(xx, f, color, r) {
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(X(xx), Y(f(xx)), r, 0, Math.PI * 2); ctx.fill();
  }
  dot(scan, function(q) { return 1 - q * q / 2; }, grey, 4);
  dot(scan, Math.cos, blue, 4.5);
  dot(a, function(q) { return 1 - q * q / 2; }, grey, 6);
  dot(a, Math.cos, blue, 6.5);
  ctx.font = '13px sans-serif';
  ctx.fillStyle = blue;
  ctx.fillText('cos x', L + 12, T + 19);
  ctx.fillStyle = grey;
  ctx.fillText('1 − x²/2', L + 12, T + 39);
}

function probe(params) {
  const b = params.beta;
  return 1 / Math.sqrt(1 - b * b) - 1;
}

function draw(ctx, state) {
  const b = Math.max(0.0001, Math.min(0.99, state.params.beta));
  const t = state.t, w = state.w, h = state.h, dark = state.dark;
  const blue = '#2f6fe4', gray = '#9aa4b2';
  const ink = dark ? '#e5e7eb' : '#273444';
  const faint = dark ? '#4b5563' : '#d7dde5';
  const K = 1 / Math.sqrt(1 - b * b) - 1;
  const Kc = 0.5 * b * b;
  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const left = Math.max(24, w * 0.08), right = w - left;
  const trackY = Math.min(76, h * 0.23);
  ctx.strokeStyle = faint;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(left, trackY);
  ctx.lineTo(right, trackY);
  ctx.stroke();
  for (let i = 0; i <= 4; i++) {
    const x = left + (right - left) * i / 4;
    ctx.beginPath();
    ctx.moveTo(x, trackY - 7);
    ctx.lineTo(x, trackY + 7);
    ctx.stroke();
  }
  const span = right - left;
  const phase = (t * b * 0.75) % 1;
  const x = left + phase * span;
  const tail = left + ((phase + 0.94) % 1) * span;
  ctx.strokeStyle = blue;
  ctx.globalAlpha = 0.28;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(tail, trackY);
  ctx.lineTo(x, trackY);
  ctx.stroke();
  ctx.globalAlpha = 1;
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(x, trackY, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.fillStyle = ink;
  ctx.font = '13px sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText('Relativistic particle', left, Math.max(17, trackY - 24));

  const gx = left + 18, gw = Math.max(20, right - left - 36);
  const gy = Math.max(trackY + 63, h * 0.43), gh = Math.max(30, h - gy - 43);
  const maxK = 1 / Math.sqrt(1 - 0.99 * 0.99) - 1;
  const X = v => gx + gw * v / 0.99;
  const Y = k => gy + gh - gh * k / maxK;
  ctx.strokeStyle = faint;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(gx, gy);
  ctx.lineTo(gx, gy + gh);
  ctx.lineTo(gx + gw, gy + gh);
  ctx.stroke();
  for (let i = 1; i <= 3; i++) {
    const yy = gy + gh * i / 4;
    ctx.beginPath();
    ctx.moveTo(gx, yy);
    ctx.lineTo(gx + gw, yy);
    ctx.stroke();
  }

  ctx.strokeStyle = blue;
  ctx.lineWidth = 3;
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const v = 0.99 * i / 100;
    const k = 1 / Math.sqrt(1 - v * v) - 1;
    if (i === 0) ctx.moveTo(X(v), Y(k)); else ctx.lineTo(X(v), Y(k));
  }
  ctx.stroke();
  ctx.strokeStyle = gray;
  ctx.lineWidth = 2;
  ctx.setLineDash([7, 5]);
  ctx.beginPath();
  ctx.moveTo(X(0), Y(0));
  ctx.lineTo(X(0.99), Y(0.5 * 0.99 * 0.99));
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.strokeStyle = faint;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(X(b), gy);
  ctx.lineTo(X(b), gy + gh);
  ctx.stroke();
  ctx.fillStyle = blue;
  ctx.beginPath();
  ctx.arc(X(b), Y(K), 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.fillStyle = gray;
  ctx.beginPath();
  ctx.arc(X(b), Y(Kc), 4, 0, 2 * Math.PI);
  ctx.fill();

  ctx.fillStyle = blue;
  ctx.font = '12px sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText('exact', gx + gw, gy + 14);
  ctx.fillStyle = gray;
  ctx.fillText('½mv²', gx + gw, gy + 31);
  ctx.fillStyle = ink;
  ctx.textAlign = 'center';
  ctx.fillText('v/c', gx + gw, gy + gh + 25);
  ctx.save();
  ctx.translate(Math.max(12, gx - 31), gy + gh / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('K / mc²', 0, 0);
  ctx.restore();
}

function probe(params) {
  var m = params.m_kg, k = params.k_Nm, k3 = params.k3_Nm3, a = params.amplitude_m;
  var dt = 2 * Math.PI * Math.sqrt(m / k) / 4000;
  var x = a, v = 0, t = 0, first = -1;
  function accel(q) { return (-k * q - k3 * q * q * q) / m; }
  for (var n = 0; n < 40000; n++) {
    var x1 = v, v1 = accel(x);
    var x2 = v + v1 * dt / 2, v2 = accel(x + x1 * dt / 2);
    var x3 = v + v2 * dt / 2, v3 = accel(x + x2 * dt / 2);
    var x4 = v + v3 * dt, v4 = accel(x + x3 * dt);
    var nx = x + dt * (x1 + 2 * x2 + 2 * x3 + x4) / 6;
    var nv = v + dt * (v1 + 2 * v2 + 2 * v3 + v4) / 6;
    if (x < 0 && nx >= 0 && nv > 0) {
      var cross = t + dt * x / (x - nx);
      if (first < 0) first = cross;
      else return cross - first;
    }
    x = nx; v = nv; t += dt;
  }
  return NaN;
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h, t = state.t;
  var bg = state.dark ? '#11161d' : '#f7f9fc';
  var faint = state.dark ? '#536071' : '#c5ccd5';
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, h);
  var amp = p.amplitude_m, omega = Math.sqrt(p.k_Nm / p.m_kg);
  var scale = Math.min(600, w * 0.75);
  var real = 35 + w * 0.38 + amp * Math.cos(omega * t) * scale;
  var rule = 35 + w * 0.38 + amp * Math.cos(omega * t) * scale;
  function system(y, end, color, label) {
    ctx.strokeStyle = faint;
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(35, y - 55); ctx.lineTo(35, y + 30); ctx.stroke();
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(35, y);
    var coils = 14, len = Math.max(15, end - 52);
    for (var i = 1; i < coils; i++) {
      var xx = 35 + len * i / coils;
      var yy = y + (i % 2 ? -13 : 13);
      ctx.lineTo(xx, yy);
    }
    ctx.lineTo(end - 17, y); ctx.stroke();
    ctx.fillStyle = color;
    ctx.fillRect(end - 17, y - 22, 34, 44);
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText(label, 48, y - 38);
  }
  system(h * 0.34, rule, '#9aa4b2', 'RULE');
  system(h * 0.66, real, '#2f6fe4', 'REAL MOTION');
  ctx.strokeStyle = faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(35 + w * 0.38, h * 0.66 - 45); ctx.lineTo(35 + w * 0.38, h * 0.66 + 45); ctx.stroke();
}

function probe(params) {
  const m = params.m_kg;
  const k = params.k_Nm;
  const k3 = params.k3_Nm3 || 0;
  const a = params.amplitude_m;
  const accel = (x) => (-k * x - k3 * x * x * x) / m;
  const target = 2 * Math.PI * Math.sqrt(m / k);
  const dt = target / 5000;
  let x = a, v = 0, t = 0, firstCrossing = null;
  for (let i = 0; i < 12000; i++) {
    const oldX = x;
    const k1x = v, k1v = accel(x);
    const k2x = v + 0.5 * dt * k1v;
    const k2v = accel(x + 0.5 * dt * k1x);
    const k3x = v + 0.5 * dt * k2v;
    const k3v = accel(x + 0.5 * dt * k2x);
    const k4x = v + dt * k3v;
    const k4v = accel(x + dt * k3x);
    x += dt * (k1x + 2 * k2x + 2 * k3x + k4x) / 6;
    v += dt * (k1v + 2 * k2v + 2 * k3v + k4v) / 6;
    t += dt;
    const crossingTime = t - dt + dt * oldX / (oldX - x);
    if (oldX > 0 && x <= 0 && firstCrossing === null) {
      firstCrossing = crossingTime;
    } else if (oldX < 0 && x >= 0 && firstCrossing !== null) {
      return 2 * (crossingTime - firstCrossing);
    }
  }
  return target;
}

function draw(ctx, state) {
  const p = state.params, w = state.w, h = state.h, dark = state.dark;
  const m = p.m_kg, k = p.k_Nm, a = p.amplitude_m;
  const omega = Math.sqrt(k / m);
  const displacement = a * Math.cos(omega * state.t);
  const predicted = a * Math.cos(omega * state.t);
  const anchor = 34, equilibrium = w * 0.55;
  const scale = Math.min(w * 0.16, h * 0.28) / a;
  const y = h * 0.53;
  const realX = equilibrium + displacement * scale;
  const ruleX = equilibrium + predicted * scale;
  const ink = dark ? '#d8dee9' : '#374151';
  ctx.clearRect(0, 0, w, h);
  ctx.lineWidth = 1;
  ctx.strokeStyle = dark ? '#4b5563' : '#d1d5db';
  ctx.setLineDash([5, 6]);
  ctx.beginPath();
  ctx.moveTo(equilibrium, h * 0.18);
  ctx.lineTo(equilibrium, h * 0.82);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.strokeStyle = ink;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(anchor, y - 55);
  ctx.lineTo(anchor, y + 55);
  ctx.stroke();
  function spring(x2, color, alpha) {
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(anchor, y);
    const end = x2 - 20, coils = 12;
    for (let i = 1; i < coils; i++) {
      const x = anchor + (end - anchor) * i / coils;
      const yy = y + (i % 2 ? -18 : 18);
      ctx.lineTo(x, yy);
    }
    ctx.lineTo(end, y);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }
  spring(ruleX, '#9aa4b2', 0.45);
  spring(realX, '#2f6fe4', 1);
  const size = 28 + 5 * Math.sqrt(m);
  ctx.globalAlpha = 0.4;
  ctx.fillStyle = '#9aa4b2';
  ctx.fillRect(ruleX - size / 2, y - size / 2, size, size);
  ctx.globalAlpha = 1;
  ctx.fillStyle = '#2f6fe4';
  ctx.fillRect(realX - size / 2, y - size / 2, size, size);
  ctx.strokeStyle = dark ? '#9db7ea' : '#2458ae';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(realX - size / 2, y - size / 2, size, size);
  ctx.strokeStyle = dark ? '#4b5563' : '#d1d5db';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(24, y + 58);
  ctx.lineTo(w - 24, y + 58);
  ctx.stroke();
}

function probe(params) {
  const m = params.m_kg;
  const k = params.k_Nm;
  const k3 = params.k3_Nm3 || 0;
  const A = Math.abs(params.amplitude_m);
  if (A === 0) return 2 * Math.PI * Math.sqrt(m / k);
  const energy = 0.5 * k * A * A + 0.25 * k3 * A * A * A * A;
  const n = 256;
  const d = (Math.PI / 2) / n;
  let sum = 0;
  for (let i = 0; i < n; i++) {
    const theta = (i + 0.5) * d;
    const x = A * Math.sin(theta);
    const potential = 0.5 * k * x * x + 0.25 * k3 * x * x * x * x;
    const speed = Math.sqrt(2 * (energy - potential) / m);
    sum += A * Math.cos(theta) / speed;
  }
  return 4 * sum * d;
}

function draw(ctx, state) {
  const p = state.params;
  const t = state.t;
  const w = state.w;
  const h = state.h;
  const dark = state.dark;
  const T = probe(p);
  const A = p.amplitude_m;
  const x = A * Math.cos(2 * Math.PI * t / T);
  const predictedPeriod = 2 * Math.PI * Math.sqrt(p.m_kg / p.k_Nm);
  const predictedX = A * Math.cos(2 * Math.PI * t / predictedPeriod);
  const cy = h * 0.43;
  const wall = 28;
  const equilibrium = w * 0.62;
  const travel = Math.min(w * 0.14, 65);
  const cx = equilibrium + travel * x / A;
  const size = 19 + 3 * Math.sqrt(p.m_kg);
  const faint = dark ? '#c3cbd6' : '#697586';
  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  ctx.strokeStyle = faint;
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(wall, cy - 55);
  ctx.lineTo(wall, cy + 55);
  ctx.moveTo(wall, cy + size + 15);
  ctx.lineTo(w - 24, cy + size + 15);
  ctx.stroke();

  const left = cx - size;
  const coils = 18;
  ctx.strokeStyle = '#2f6fe4';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(wall, cy);
  ctx.lineTo(wall + 14, cy);
  for (let i = 0; i <= coils; i++) {
    const sx = wall + 14 + (left - wall - 28) * i / coils;
    const sy = cy + (i === 0 || i === coils ? 0 : (i % 2 ? -18 : 18));
    ctx.lineTo(sx, sy);
  }
  ctx.lineTo(left, cy);
  ctx.stroke();

  ctx.fillStyle = '#2f6fe4';
  ctx.fillRect(cx - size, cy - size, size * 2, size * 2);
  ctx.strokeStyle = dark ? '#d8e5ff' : '#174da8';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(cx - size, cy - size, size * 2, size * 2);

  const gx = 45;
  const gw = w - 90;
  const gy = h * 0.79;
  const ga = Math.min(34, h * 0.12);
  ctx.strokeStyle = faint;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(gx, gy);
  ctx.lineTo(gx + gw, gy);
  ctx.stroke();

  ctx.strokeStyle = '#9aa4b2';
  ctx.lineWidth = 3;
  ctx.setLineDash([7, 5]);
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const q = i / 100;
    const xx = gx + q * gw;
    const yy = gy - ga * Math.cos(2 * Math.PI * q);
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.strokeStyle = '#2f6fe4';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const q = i / 100;
    const xx = gx + q * gw;
    const yy = gy - ga * Math.cos(2 * Math.PI * q);
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.stroke();

  const markerX = gx + ((t % T) / T) * gw;
  ctx.fillStyle = '#9aa4b2';
  ctx.beginPath();
  ctx.arc(markerX, gy - ga * predictedX / A, 5, 0, 2 * Math.PI);
  ctx.fill();
  ctx.fillStyle = '#2f6fe4';
  ctx.beginPath();
  ctx.arc(markerX, gy - ga * x / A, 4, 0, 2 * Math.PI);
  ctx.fill();
}

function probe(params){
  var A=params.amplitude_m, m=params.m_kg, k=params.k_Nm, k3=params.k3_Nm3;
  if(k3===0) return 2*Math.PI*Math.sqrt(m/k);
  var tau=Math.sqrt(m/k), dt=tau/500;
  var x=A, v=0, t=0, px=x, pt=t;
  function acc(x){return (-k*x-k3*x*x*x)/m;}
  for(var i=0;i<20000;i++){
    var k1x=v, k1v=acc(x);
    var k2x=v+k1v*dt/2, k2v=acc(x+k1x*dt/2);
    var k3x=v+k2v*dt/2, k3v=acc(x+k2x*dt/2);
    var k4x=v+k3v*dt, k4v=acc(x+k3x*dt);
    px=x; pt=t;
    x+=dt*(k1x+2*k2x+2*k3x+k4x)/6;
    v+=dt*(k1v+2*k2v+2*k3v+k4v)/6;
    t+=dt;
    if(t>2*tau && x>=A && v>0){
      var f=(A-px)/(x-px);
      return pt+f*dt;
    }
  }
  return 2*Math.PI*tau;
}
