      return 4 * (oldT + f * dt);
    }
  }
  return 2 * Math.PI * Math.sqrt(L / g);
}

function draw(ctx, state) {
  var p = state.params, w = state.w, h = state.h, dark = state.dark;
  var L = Math.max(0.0001, Number(p.L_m));
  var A = (Number(p.amplitude_deg) || 0) * Math.PI / 180;
  var g = 9.81;
  var base = 2 * Math.PI * Math.sqrt(L / g);
  var a = 1, b = Math.cos(Math.abs(A) / 2);
  for (var i = 0; i < 8; i++) {
    var na = (a + b) / 2;
    b = Math.sqrt(a * b);
    a = na;
  }
  var realPeriod = base / a;
  var thetaReal = A * Math.cos(2 * Math.PI * state.t / realPeriod);
  var thetaRule = A * Math.cos(2 * Math.PI * state.t / base);
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = dark ? '#111827' : '#ffffff';
  ctx.fillRect(0, 0, w, h);
  var x0 = w / 2, y0 = Math.max(38, h * 0.14);
  var len = Math.min(h * 0.65, w * 0.55);
  function pos(th) { return { x: x0 + len * Math.sin(th), y: y0 + len * Math.cos(th) }; }
  var pr = pos(thetaRule), pe = pos(thetaReal);
  ctx.strokeStyle = dark ? '#4b5563' : '#d5dae1';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(x0, y0, len, Math.PI / 2 - A, Math.PI / 2 + A);
  ctx.stroke();
  ctx.strokeStyle = '#9aa4b2';
  ctx.fillStyle = '#9aa4b2';
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(pr.x, pr.y); ctx.stroke();
  ctx.beginPath(); ctx.arc(pr.x, pr.y, 10, 0, 2 * Math.PI); ctx.fill();
  ctx.strokeStyle = '#2f6fe4';
  ctx.fillStyle = '#2f6fe4';
  ctx.lineWidth = 2.5;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(pe.x, pe.y); ctx.stroke();
  ctx.beginPath(); ctx.arc(pe.x, pe.y, 13, 0, 2 * Math.PI); ctx.fill();
  ctx.fillStyle = dark ? '#e5e7eb' : '#374151';
  ctx.beginPath(); ctx.arc(x0, y0, 4, 0, 2 * Math.PI); ctx.fill();
  ctx.font = '13px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillStyle = '#2f6fe4';
  ctx.fillText('Real pendulum', w / 2, h - 34);
  ctx.fillStyle = '#9aa4b2';
  ctx.fillText('Formula prediction', w / 2, h - 16);
}

function period(params){
  var L=params.L_m, g=9.81, a=params.amplitude_deg*Math.PI/180;
  var x=1, y=Math.cos(a/2);
  for(var i=0;i<12;i++){var n=(x+y)/2; y=Math.sqrt(x*y); x=n;}
  return 2*Math.PI*Math.sqrt(L/g)/x;
}
function probe(params){return period(params);}
function draw(ctx,state){
  var p=state.params, t=state.t, w=state.w, h=state.h, dark=state.dark;
  var g=9.81, L=p.L_m, A=p.amplitude_deg*Math.PI/180;
  var T=period(p), T0=2*Math.PI*Math.sqrt(L/g), blue='#2f6fe4', gray='#9aa4b2';
  ctx.clearRect(0,0,w,h);
  var px=w/2, py=h*0.16, len=Math.min(h*0.66,w*0.4);
  var faint=dark?'#536071':'#c7cdd4', text=dark?'#d7dde5':'#48515b';
  ctx.strokeStyle=faint; ctx.lineWidth=1; ctx.setLineDash([4,5]);
  ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(px,py+len); ctx.stroke(); ctx.setLineDash([]);
  ctx.strokeStyle=dark?'#354454':'#d7e1ee';
  ctx.beginPath(); ctx.arc(px,py,len,-Math.PI/2-A,-Math.PI/2+A); ctx.stroke();
  var u=((t%T)+T)%T, th=A, om=0, dt=u/240;
  function deriv(a,b){return [b,-g/L*Math.sin(a)];}
  for(var i=0;i<240&&dt>0;i++){
    var k1=deriv(th,om), k2=deriv(th+k1[0]*dt/2,om+k1[1]*dt/2);
    var k3=deriv(th+k2[0]*dt/2,om+k2[1]*dt/2), k4=deriv(th+k3[0]*dt,om+k3[1]*dt);
    th+=dt*(k1[0]+2*k2[0]+2*k3[0]+k4[0])/6;
    om+=dt*(k1[1]+2*k2[1]+2*k3[1]+k4[1])/6;
  }
  var pred=A*Math.cos(2*Math.PI*t/T0);
  var gx=px+len*Math.sin(pred), gy=py+len*Math.cos(pred);
  var bx=px+len*Math.sin(th), by=py+len*Math.cos(th);
  ctx.globalAlpha=0.55; ctx.strokeStyle=gray; ctx.fillStyle=gray; ctx.lineWidth=1.5;
  ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(gx,gy); ctx.stroke();
  ctx.beginPath(); ctx.arc(gx,gy,9,0,2*Math.PI); ctx.fill(); ctx.globalAlpha=1;
  ctx.strokeStyle=blue; ctx.fillStyle=blue; ctx.lineWidth=2.5;
  ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(bx,by); ctx.stroke();
  ctx.beginPath(); ctx.arc(bx,by,14,0,2*Math.PI); ctx.fill();
  ctx.fillStyle=text; ctx.beginPath(); ctx.arc(px,py,4,0,2*Math.PI); ctx.fill();
}

const G = 9.81;

function truePeriod(a, L) {
  if (a === 0) return 2 * Math.PI * Math.sqrt(L / G);
  const k = Math.sin(a / 2);
  let x = 1, y = Math.sqrt(1 - k * k);
  for (let i = 0; i < 12 && Math.abs(x - y) > 1e-15; i++) {
    const next = (x + y) / 2;
    y = Math.sqrt(x * y);
    x = next;
  }
  return 2 * Math.PI * Math.sqrt(L / G) / x;
}

function probe(params) {
  return truePeriod(params.amplitude_deg * Math.PI / 180, params.L_m);
}

function draw(ctx, state) {
  const a = state.params.amplitude_deg * Math.PI / 180;
  const L = state.params.L_m;
  const w = state.w, h = state.h;
  const ink = state.dark ? '#d7dee8' : '#65717f';
  const faint = state.dark ? '#465366' : '#c5ccd5';
  ctx.clearRect(0, 0, w, h);

  const p = truePeriod(a, L);
  let phase = state.t % p;
  let theta = a, velocity = 0;
  const steps = Math.max(1, Math.ceil(phase * 240));
  const dt = phase / steps;
  for (let i = 0; i < steps; i++) {
    const k1t = velocity, k1v = -G / L * Math.sin(theta);
    const k2t = velocity + dt * k1v / 2;
    const k2v = -G / L * Math.sin(theta + dt * k1t / 2);
    const k3t = velocity + dt * k2v / 2;
    const k3v = -G / L * Math.sin(theta + dt * k2t / 2);
    const k4t = velocity + dt * k3v;
    const k4v = -G / L * Math.sin(theta + dt * k3t);
    theta += dt * (k1t + 2 * k2t + 2 * k3t + k4t) / 6;
    velocity += dt * (k1v + 2 * k2v + 2 * k3v + k4v) / 6;
  }
  const predicted = a * Math.cos(Math.sqrt(G / L) * state.t);

  const top = h * 0.17;
  const length = Math.min(h * 0.59, w * 0.31);
  const centers = [w * 0.30, w * 0.72];
  const angles = [theta, predicted];
  const colors = ['#2f6fe4', '#9aa4b2'];
  const labels = ['Real motion', 'Small-angle rule'];

  ctx.lineWidth = 1;
  ctx.font = '12px sans-serif';
  ctx.textAlign = 'center';
  for (let j = 0; j < 2; j++) {
    const x = centers[j];
    ctx.strokeStyle = faint;
    ctx.beginPath();
    ctx.moveTo(x - 28, top);
    ctx.lineTo(x + 28, top);
    ctx.stroke();
    ctx.setLineDash([3, 5]);
    ctx.beginPath();
    ctx.moveTo(x, top);
    ctx.lineTo(x, top + length + 10);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x, top, length, Math.PI / 2 - a, Math.PI / 2 + a);
    ctx.stroke();
    ctx.setLineDash([]);

    const bx = x + length * Math.sin(angles[j]);
    const by = top + length * Math.cos(angles[j]);
    ctx.strokeStyle = colors[j];
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x, top);
    ctx.lineTo(bx, by);
    ctx.stroke();
    ctx.fillStyle = colors[j];
    ctx.beginPath();
    ctx.arc(bx, by, Math.max(7, Math.min(12, w / 40)), 0, 2 * Math.PI);
    ctx.fill();
    ctx.fillStyle = ink;
    ctx.fillText(labels[j], x, Math.min(h - 8, top + length + 32));
  }
}

const G = 9.81;

function pendulumPeriod(amplitudeDeg, L) {
  const half = amplitudeDeg * Math.PI / 360;
  let a = 1, b = Math.cos(half);
  for (let i = 0; i < 24; i++) {
    const nextA = (a + b) / 2;
    b = Math.sqrt(a * b);
    a = nextA;
    if (Math.abs(a - b) < 1e-15 * a) break;
  }
  return 2 * Math.PI * Math.sqrt(L / G) / a;
}

function probe(params) {
  return pendulumPeriod(params.amplitude_deg, params.L_m);
}

let waveCache = null;

function makeWave(amplitudeDeg, L) {
  const T = pendulumPeriod(amplitudeDeg, L);
  const N = 720, dt = T / N;
  const values = new Float64Array(N + 1);
  let theta = amplitudeDeg * Math.PI / 180, omega = 0;
  values[0] = theta;
  function accel(th) { return -G / L * Math.sin(th); }
  for (let i = 1; i <= N; i++) {
    const k1t = omega, k1w = accel(theta);
    const k2t = omega + dt * k1w / 2;
    const k2w = accel(theta + dt * k1t / 2);
    const k3t = omega + dt * k2w / 2;
    const k3w = accel(theta + dt * k2t / 2);
    const k4t = omega + dt * k3w;
    const k4w = accel(theta + dt * k3t);
    theta += dt * (k1t + 2 * k2t + 2 * k3t + k4t) / 6;
    omega += dt * (k1w + 2 * k2w + 2 * k3w + k4w) / 6;
    values[i] = theta;
  }
  values[N] = values[0];
  return { amplitudeDeg, L, T, N, values };
}

function realAngle(cache, t) {
  let phase = (t / cache.T) % 1;
  if (phase < 0) phase += 1;
  const x = phase * cache.N, i = Math.floor(x), f = x - i;
  return cache.values[i] * (1 - f) + cache.values[i + 1] * f;
}

function draw(ctx, state) {
  const { params, t, w, h, dark } = state;
  const A = params.amplitude_deg, L = params.L_m;
  if (!waveCache || waveCache.amplitudeDeg !== A || waveCache.L !== L) {
    waveCache = makeWave(A, L);
  }
  const theta = realAngle(waveCache, t);
  const predicted = A * Math.PI / 180 * Math.cos(Math.sqrt(G / L) * t);
  const px = w / 2, py = h * 0.20;
  const r = Math.min(w * 0.35, h * 0.64);
  const line = dark ? '#c7d0dc' : '#596574';

  ctx.clearRect(0, 0, w, h);
  ctx.lineCap = 'round';

  const amplitude = A * Math.PI / 180;
  ctx.beginPath();
  ctx.arc(px, py, r, Math.PI / 2 - amplitude, Math.PI / 2 + amplitude);
  ctx.strokeStyle = dark ? 'rgba(200,212,226,0.18)' : 'rgba(90,102,116,0.16)';
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.beginPath();
  for (let j = 0; j <= 36; j++) {
    const th = realAngle(waveCache, t - 0.8 + 0.8 * j / 36);
    const x = px + r * Math.sin(th), y = py + r * Math.cos(th);
    if (j === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.strokeStyle = 'rgba(47,111,228,0.25)';
  ctx.lineWidth = 3;
  ctx.stroke();

  function pendulum(th, color, rodWidth, bobRadius) {
    const x = px + r * Math.sin(th), y = py + r * Math.cos(th);
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(x, y);
    ctx.strokeStyle = color;
    ctx.lineWidth = rodWidth;
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x, y, bobRadius, 0, 2 * Math.PI);
    ctx.fillStyle = color;
    ctx.fill();
  }

  pendulum(predicted, '#9aa4b2', 1.5, 8);
  pendulum(theta, '#2f6fe4', 2.5, 12);

  ctx.beginPath();
  ctx.moveTo(px - 22, py);
  ctx.lineTo(px + 22, py);
  ctx.strokeStyle = line;
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(px, py, 3.5, 0, 2 * Math.PI);
  ctx.fillStyle = line;
  ctx.fill();
}
